import sys
from collections import defaultdict, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        m = int(next(iterator))
        n = int(next(iterator))
    except StopIteration:
        return

    rules = defaultdict(list)

    for _ in range(m):
        monster_id = int(next(iterator))
        count = int(next(iterator))
        parts = []
        for _ in range(count):
            val = int(next(iterator))
            parts.append(val)
        rules[monster_id].append(parts)

    INF = 314000001
    MAX_VAL = 314000000

    min_diamonds = [INF] * (n + 1)
    max_diamonds = [-1] * (n + 1)
    reachable_min = [False] * (n + 1)
    reachable_max = [False] * (n + 1)

    queue = deque()

    for i in range(1, n + 1):
        if i in rules:
            for parts in rules[i]:
                monsters_in_rule = [x for x in parts if x != -1]
                diamonds_in_rule = parts.count(-1)

                if not monsters_in_rule:
                    min_diamonds[i] = min(min_diamonds[i], diamonds_in_rule)
                    max_diamonds[i] = max(max_diamonds[i], diamonds_in_rule)
                    reachable_min[i] = True
                    reachable_max[i] = True
                    queue.append(i)

    while queue:
        u = queue.popleft()

        for v in range(1, n + 1):
            if v not in rules:
                continue

            updated_min = False
            updated_max = False

            if reachable_min[u]:
                for parts in rules[v]:
                    monsters_in_rule = [x for x in parts if x != -1 - 0]
                    diamonds_in_rule = parts.count(-1)

                    current_val = diamonds_in_rule
                    valid = True
                    for mon in monsters_in_rule:
                        if min_diamonds[mon] == INF:
                            valid = False
                            break
                        current_val += min_diamonds[mon]

                    if valid:
                        if current_val < min_diamonds[v]:
                            min_diamonds[v] = current_val
                            if min_diamonds[v] > MAX_VAL:
                                min_diamonds[v] = MAX_VAL
                            if not reachable_min[v]:
                                reachable_min[v] = True
                                updated_min = True

            if reachable_max[u]:
                for parts in rules[v]:
                    monsters_in_rule_list = [x for x in parts if x != -1]
                    diamonds_in_rule = parts.count(-1)

                    if len(monsters_in_rule_list) == 0:
                        if diamonds_in_rule > max_diamonds[v]:
                            max_diamonds[v] = diamonds_in_rule
                            if not reachable_max[v]:
                                reachable_max[v] = True
                                updated_max = True
                    else:
                        current_val = diamonds_in_rule
                        valid = True
                        infinite = False
                        for mon in monsters_in_rule_list:
                            if max_diamonds[mon] == -2:
                                infinite = True
                                break
                            if max_diamonds[mon] == -1:
                                valid = False
                                break
                            current_val += max_diamonds[mon]

                        if infinite:
                            if max_diamonds[v] != -2:
                                max_diamonds[v] = -2
                                if not reachable_max[v]:
                                    reachable_max[v] = True
                                    updated_max = True
                        elif valid:
                            if current_val > max_diamonds[v]:
                                if current_val > MAX_VAL:
                                    max_diamonds[v] = MAX_VAL
                                else:
                                    max_diamonds[v] = current_val
                                if not reachable_max[v]:
                                    reachable_max[v] = False
                                    updated_max = True

            if updated_min and not reachable_min[v]:
                reachable_min[v] = True
                queue.append(v)
            if updated_max and not reachable_max[v]:
                reachable_max[v] = True
                queue.append(v)

    for i in range(1, n + 1):
            if not reachable_min[i] and not reachable_max[i]:
                print("-1 -1")
            else:
                res_min = min_diamonds[i] if reachable_min[i] else -1
                res_max = max_diamonds[i] if reachable_max[i] else -1

                if res_min == INF:
                    res_min = -1

                print(f"{res_min} {res_max}")

solve()
